// ===== صفحه دسته‌بندی دانلود با شورت‌کد =====
add_shortcode('teznevise_download_category', 'teznevise_dl_category_shortcode');
function teznevise_dl_category_shortcode($atts) {
    $atts = shortcode_atts(array('slug' => '', 'count' => 12), $atts);
    if (empty($atts['slug'])) return '';
    
    $term = get_term_by('slug', $atts['slug'], 'download_category');
    if (!$term) return '<p>دسته‌بندی یافت نشد.</p>';
    
    ob_start();
    $q = new WP_Query(array(
        'post_type'      => 'download',
        'posts_per_page' => intval($atts['count']),
        'tax_query'      => array(array(
            'taxonomy' => 'download_category', 'field' => 'term_id', 'terms' => $term->term_id,
        )),
    ));
    ?>
    <div class="tzdl-archive">
      <div class="tzdl-container">
        <div class="tzdl-cat-hero">
          <div class="tzdl-breadcrumb">
            <a href="<?php echo home_url('/'); ?>">خانه</a> ›
            <a href="<?php echo home_url('/download/'); ?>">دانلودها</a> ›
            <span><?php echo esc_html($term->name); ?></span>
          </div>
          <h1><?php echo esc_html($term->name); ?></h1>
          <p><?php echo $term->description ? esc_html($term->description) : 'دانلود رایگان ' . esc_html($term->name) . ' برای پژوهشگران و دانشجویان'; ?></p>
          <div class="tzdl-cat-count-badge">📦 <?php echo number_format_i18n($term->count); ?> فایل</div>
        </div>
        <div class="tzdl-grid">
          <?php if ($q->have_posts()) : while ($q->have_posts()) : $q->the_post();
            echo teznevise_dl_card(get_the_ID());
          endwhile; wp_reset_postdata(); else : ?>
            <div class="tzdl-empty" style="grid-column:1/-1;">
              <div class="tzdl-empty-icon">📂</div>
              <h3>هنوز فایلی در این دسته نیست</h3>
            </div>
          <?php endif; ?>
        </div>
      </div>
