// ===== ۶. ذخیره متاباکس‌ها =====
add_action( 'save_post_download', 'teznevise_save_download_meta' );

function teznevise_save_download_meta( $post_id ) {
    if ( ! isset( $_POST['teznevise_download_nonce'] ) ||
         ! wp_verify_nonce( $_POST['teznevise_download_nonce'], 'teznevise_download_save' ) ) {
        return;
    }

    if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) {
        return;
    }

    if ( ! current_user_can( 'edit_post', $post_id ) ) {
        return;
    }

    // ذخیره لینک‌های دانلود
    if ( isset( $_POST['tz_dl_text'] ) ) {
        $links = array();
        $texts = $_POST['tz_dl_text'];
        $urls  = $_POST['tz_dl_url'];
        $exts  = $_POST['tz_dl_ext'];
        $sizes = $_POST['tz_dl_size'];

        for ( $i = 0; $i < count( $texts ); $i++ ) {
            if ( ! empty( $urls[ $i ] ) ) {
                $links[] = array(
                    'text' => sanitize_text_field( $texts[ $i ] ),
                    'url'  => esc_url_raw( $urls[ $i ] ),
                    'ext'  => sanitize_text_field( $exts[ $i ] ),
                    'size' => sanitize_text_field( $sizes[ $i ] ),
                );
            }
        }

        update_post_meta( $post_id, '_teznevise_download_links', $links );
    }

    // ذخیره اطلاعات تکمیلی
    $fields = array(
        'tz_version' => '_teznevise_version',
        'tz_license' => '_teznevise_license',
        'tz_lang'    => '_teznevise_lang',
        'tz_source'  => '_teznevise_source',
    );

    foreach ( $fields as $post_key => $meta_key ) {
        if ( isset( $_POST[ $post_key ] ) ) {
            update_post_meta( $post_id, $meta_key, sanitize_text_field( $_POST[ $post_key ] ) );
        }
    }

    // شمارش دانلود اولیه (اگر نباشد)
    if ( get_post_meta( $post_id, '_teznevise_download_count', true ) === '' ) {
        update_post_meta( $post_id, '_teznevise_download_count', 0 );
    }
}


