} );

add_action( 'manage_download_posts_custom_column', function ( $col, $post_id ) {
    if ( $col === 'tz_downloads' ) {
        echo number_format_i18n( intval( get_post_meta( $post_id, '_teznevise_download_count', true ) ) );
    }

    if ( $col === 'tz_files' ) {
        $links = get_post_meta( $post_id, '_teznevise_download_links', true );
