// ===== ۸. AJAX شمارش دانلود =====
add_action( 'wp_ajax_teznevise_count_download',        'teznevise_count_download' );
add_action( 'wp_ajax_nopriv_teznevise_count_download', 'teznevise_count_download' );

function teznevise_count_download() {
    $post_id = isset( $_POST['post_id'] ) ? intval( $_POST['post_id'] ) : 0;

    if ( $post_id ) {
        $count = intval( get_post_meta( $post_id, '_teznevise_download_count', true ) );
        update_post_meta( $post_id, '_teznevise_download_count', $count + 1 );
        wp_send_json_success( array( 'count' => $count + 1 ) );
    }

    wp_send_json_error();
}

