// ===== ۱. تابع کمکی: حروف اول نام =====
if ( ! function_exists( 'teznevise_dl_initials' ) ) {
    function teznevise_dl_initials( $name ) {
        $parts = explode( ' ', trim( $name ) );
        $out   = '';

        foreach ( $parts as $p ) {
            if ( $p !== '' ) {
                $out .= mb_substr( $p, 0, 1, 'UTF-8' );
                if ( mb_strlen( $out, 'UTF-8' ) >= 2 ) {
                    break;
                }
            }
        }

        return $out ?: '📄';
    }
}


