add_action('save_post_case_study', 'teznevise_save_cs_meta');
function teznevise_save_cs_meta($post_id) {
    if (!isset($_POST['tz_cs_nonce']) || !wp_verify_nonce($_POST['tz_cs_nonce'], 'tz_cs_save')) return;
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) return;
    if (!current_user_can('edit_post', $post_id)) return;

    $text_fields = array(
        'tz_cs_icon'=>'_tz_cs_icon','tz_cs_client'=>'_tz_cs_client','tz_cs_field'=>'_tz_cs_field',
        'tz_cs_degree'=>'_tz_cs_degree','tz_cs_service'=>'_tz_cs_service','tz_cs_duration'=>'_tz_cs_duration',
        'tz_cs_region'=>'_tz_cs_region','tz_cs_tools'=>'_tz_cs_tools',
    );
    foreach ($text_fields as $pk=>$mk) {
        if (isset($_POST[$pk])) update_post_meta($post_id, $mk, sanitize_text_field($_POST[$pk]));
    }

    $textarea_fields = array(
        'tz_cs_challenge'=>'_tz_cs_challenge','tz_cs_solution'=>'_tz_cs_solution',
        'tz_cs_result'=>'_tz_cs_result','tz_cs_quote'=>'_tz_cs_quote',
    );
    foreach ($textarea_fields as $pk=>$mk) {
        if (isset($_POST[$pk])) update_post_meta($post_id, $mk, sanitize_textarea_field($_POST[$pk]));
    }

    // متریک‌ها
    if (isset($_POST['tz_metric_value'])) {
        $metrics = array();
        $vals = $_POST['tz_metric_value']; $labels = $_POST['tz_metric_label'];
        for ($i=0; $i<count($vals); $i++) {
            if (!empty($vals[$i]) || !empty($labels[$i])) {
                $metrics[] = array('value'=>sanitize_text_field($vals[$i]), 'label'=>sanitize_text_field($labels[$i]));
            }
        }
        update_post_meta($post_id, '_tz_cs_metrics', $metrics);
    }
}

