add_action('wp_head', 'teznevise_cs_schema');
function teznevise_cs_schema() {
    if (is_singular('case_study')) {
        $pid = get_the_ID();
        $field = get_post_meta($pid,'_tz_cs_field',true);
        $thumb = get_the_post_thumbnail_url($pid,'large');

        $schema = array(
            '@context'=>'https://schema.org','@type'=>'Article',
            'headline'=>get_the_title(),
            'description'=>wp_strip_all_tags(get_the_excerpt()),
            'datePublished'=>get_the_date('c'),
            'dateModified'=>get_the_modified_date('c'),
            'author'=>array('@type'=>'Organization','name'=>'تزنویسه'),
            'publisher'=>array('@type'=>'Organization','name'=>'تزنویسه','logo'=>array('@type'=>'ImageObject','url'=>get_site_icon_url())),
            'mainEntityOfPage'=>get_permalink(),
            'articleSection'=>$field,
            'inLanguage'=>'fa-IR',
        );
        if ($thumb) $schema['image']=$thumb;
        echo "\n".'<script type="application/ld+json">'.wp_json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>'."\n";

        // Breadcrumb
        $bc = array('@context'=>'https://schema.org','@type'=>'BreadcrumbList','itemListElement'=>array(
            array('@type'=>'ListItem','position'=>1,'name'=>'خانه','item'=>home_url('/')),
            array('@type'=>'ListItem','position'=>2,'name'=>'مطالعات موردی','item'=>home_url('/case-studies/')),
            array('@type'=>'ListItem','position'=>3,'name'=>get_the_title(),'item'=>get_permalink()),
        ));
        echo '<script type="application/ld+json">'.wp_json_encode($bc,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>'."\n";
    }

    if (is_post_type_archive('case_study') || is_tax('case_category')) {
        $schema = array('@context'=>'https://schema.org','@type'=>'CollectionPage',
            'name'=>'مطالعات موردی تزنویسه',
            'description'=>'روایت پروژه‌های پژوهشی موفق تزنویسه شامل چالش، راهکار و نتیجه',
            'url'=>home_url('/case-studies/'),'inLanguage'=>'fa-IR');
        echo "\n".'<script type="application/ld+json">'.wp_json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>'."\n";
    }
}

