    <script>
    (function(){
      var COOKIE_NAME = 'tz_cookie_consent';
      var COOKIE_DAYS = 180;
      var CONSENT_VERSION = '2.3';   // bump to force re-prompt after policy changes

      function setCookie(n,v,d){ var e=new Date(); e.setTime(e.getTime()+(d*864e5)); document.cookie=n+'='+encodeURIComponent(v)+';expires='+e.toUTCString()+';path=/;SameSite=Lax'; }
      function getCookie(n){ var m=document.cookie.match(new RegExp('(^| )'+n+'=([^;]+)')); return m?decodeURIComponent(m[2]):null; }

      window.dataLayer = window.dataLayer || [];
      function gtag(){ dataLayer.push(arguments); }
      window.gtag = window.gtag || gtag;

      var banner = document.getElementById('tz-cookie-banner');
      var reopen = document.getElementById('tz-cookie-reopen');

      function showBanner(){ if(banner){ banner.classList.remove('tz-cookie-closing'); banner.style.display='block'; } if(reopen) reopen.style.display='none'; }
      function hideBanner(){
        if(banner){
          banner.classList.add('tz-cookie-closing');
          setTimeout(function(){ banner.style.display='none'; banner.classList.remove('tz-cookie-closing'); }, 400);
        }
        if(reopen) reopen.style.display='block';
      }

      /* ===== Decide whether to show the banner ===== */
      var existing = null;
      try { existing = JSON.parse(getCookie(COOKIE_NAME)); } catch(e){ existing = null; }

      if (!existing || existing.version !== CONSENT_VERSION) {
        showBanner();
        if (existing) applyConsent(existing); // honor old choice until they re-decide
      } else {
        applyConsent(existing);
        if(reopen) reopen.style.display='block';
      }

      /* ===== Push consent state to Google + Clarity + dataLayer ===== */
      function applyConsent(c){
        // 1) Google Consent Mode v2 — update
        gtag('consent', 'update', {
          'ad_storage':             c.marketing  ? 'granted' : 'denied',
          'ad_user_data':           c.marketing  ? 'granted' : 'denied',
          'ad_personalization':     c.marketing  ? 'granted' : 'denied',
          'analytics_storage':      c.analytics  ? 'granted' : 'denied',
          'functionality_storage':  c.functional ? 'granted' : 'denied',
          'personalization_storage':c.functional ? 'granted' : 'denied',
          'security_storage':       'granted'
        });

        // 2) Microsoft Clarity — gate on analytics consent
        try {
          if (typeof window.clarity === 'function') {
            window.clarity('consent', !!c.analytics);
          }
        } catch(e){}

        // 3) Custom events for any non-Google tools
        if(c.analytics)  document.dispatchEvent(new CustomEvent('tzConsentAnalytics'));
        if(c.marketing)  document.dispatchEvent(new CustomEvent('tzConsentMarketing'));
        if(c.functional) document.dispatchEvent(new CustomEvent('tzConsentFunctional'));

        // 4) dataLayer event for GTM triggers
        dataLayer.push({
          event: 'tz_consent_update',
          tz_consent_analytics:  !!c.analytics,
          tz_consent_marketing:  !!c.marketing,
          tz_consent_functional: !!c.functional
        });
      }

      function saveConsent(c){
        c.timestamp = new Date().toISOString();
        c.version   = CONSENT_VERSION;
        setCookie(COOKIE_NAME, JSON.stringify(c), COOKIE_DAYS);
        applyConsent(c);
        hideBanner();
      }

      /* ===== Public actions ===== */
      window.tzCookieAcceptAll = function(){ saveConsent({necessary:true,functional:true,analytics:true,marketing:true}); };
      window.tzCookieRejectAll = function(){ saveConsent({necessary:true,functional:false,analytics:false,marketing:false}); };

      window.tzCookieShowSettings = function(){
        document.getElementById('tz-cookie-main').style.display='none';
        document.getElementById('tz-cookie-settings').style.display='block';
        var c = null; try { c = JSON.parse(getCookie(COOKIE_NAME)); } catch(e){}
        if (c) {
          document.getElementById('tz-cookie-functional').checked = !!c.functional;
          document.getElementById('tz-cookie-analytics').checked  = !!c.analytics;
          document.getElementById('tz-cookie-marketing').checked  = !!c.marketing;
        }
      };
      window.tzCookieShowMain = function(){
        document.getElementById('tz-cookie-settings').style.display='none';
        document.getElementById('tz-cookie-main').style.display='block';
      };
      window.tzCookieSaveSettings = function(){
        saveConsent({
          necessary:true,
          functional:document.getElementById('tz-cookie-functional').checked,
          analytics:document.getElementById('tz-cookie-analytics').checked,
          marketing:document.getElementById('tz-cookie-marketing').checked
        });
      };

      // Close (✕) without choosing = reject all but necessary (GDPR-safe)
      window.tzCookieDismiss = function(){
        if (!getCookie(COOKIE_NAME)) {
          saveConsent({necessary:true,functional:false,analytics:false,marketing:false,dismissed:true});
        } else {
          hideBanner();
        }
      };

      // Re-open from the floating 🍪 button (withdraw/change consent)
      window.tzCookieReopen = function(){
        window.tzCookieShowMain();
        showBanner();
      };
    })();
