              <tr><td>۰.۶۰ - ۰.۷۹</td><td>خوب (Good)</td></tr>
              <tr><td>۰.۴۰ - ۰.۵۹</td><td>قابل قبول (Moderate)</td></tr>
              <tr><td>۰.۲۰ - ۰.۳۹</td><td>ضعیف (Fair)</td></tr>
              <tr><td>< ۰.۲۰</td><td>بد (Poor)</td></tr>
