if ( ! function_exists( 'tz_verify_turnstile' ) ) {
    function tz_verify_turnstile( string $token ): bool {
        if ( empty( $token ) ) return false;
        $res = wp_remote_post(
            'https://challenges.cloudflare.com/turnstile/v0/siteverify',
            [ 'timeout' => 15, 'body' => [
                'secret'   => TZ_TURNSTILE_SECRET_KEY,
                'response' => $token,
                'remoteip' => tz_get_client_ip(),
            ] ]
        );
        if ( is_wp_error( $res ) ) { error_log( '[TZ TURNSTILE] ' . $res->get_error_message() ); return false; }
        $body = json_decode( wp_remote_retrieve_body( $res ), true );
        if ( empty( $body['success'] ) ) error_log( '[TZ TURNSTILE] failed: ' . wp_json_encode( $body['error-codes'] ?? [] ) );
        return ! empty( $body['success'] );
    }
}

/* ============================================================ دریافت IP ============================================================ */
if ( ! function_exists( 'tz_get_client_ip' ) ) {
    function tz_get_client_ip(): string {
        foreach ( [ 'HTTP_CF_CONNECTING_IP','HTTP_X_FORWARDED_FOR','HTTP_X_REAL_IP','REMOTE_ADDR' ] as $key ) {
            if ( ! empty( $_SERVER[ $key ] ) ) {
                $ip = trim( explode( ',', sanitize_text_field( wp_unslash( $_SERVER[ $key ] ) ) )[0] );
                if ( filter_var( $ip, FILTER_VALIDATE_IP ) ) return $ip;
            }
        }
        return '0.0.0.0';
    }
}

