function tz_float_contact_handler_v6() {

    if ( ! check_ajax_referer( 'tz_float_contact_nonce', '_nonce', false ) )
        wp_send_json_error( [ 'message' => 'درخواست نامعتبر است.' ], 403 );

    $ts_token = sanitize_text_field( wp_unslash( $_POST['cf-turnstile-response'] ?? '' ) );
    if ( empty( $ts_token ) )
        wp_send_json_error( [ 'message' => 'لطفاً تأیید امنیتی را تکمیل کنید.' ], 403 );
    if ( ! tz_verify_turnstile( $ts_token ) )
        wp_send_json_error( [ 'message' => 'تأیید امنیتی ناموفق بود. دوباره تلاش کنید.' ], 403 );

    $ip       = tz_get_client_ip();
    $rate_key = 'tz_fc_rate_' . md5( $ip );

    // FIX 2: check for an existing lock (read-only) here, but do NOT
    // set a new lock yet. Locking happens further down, only once we
    // know this is a genuinely valid, well-formed submission. This is
    // the change described in the file header — previously the lock
    // was created here unconditionally, so a mistyped phone number on
    // attempt #1 blocked the correction on attempt #2 for 60 seconds.
    if ( get_transient( $rate_key ) )
        wp_send_json_error( [ 'message' => 'لطفاً ۶۰ ثانیه صبر کنید.', 'rate_limited' => true ], 429 );

    $name       = sanitize_text_field( wp_unslash( $_POST['tz_c_name']       ?? '' ) );
    $phone      = sanitize_text_field( wp_unslash( $_POST['tz_c_phone']      ?? '' ) );
    $page_url   = esc_url_raw(         wp_unslash( $_POST['tz_c_page_url']   ?? '' ) );
    $page_title = sanitize_text_field( wp_unslash( $_POST['tz_c_page_title'] ?? '' ) );
    $time_on    = absint(                            $_POST['tz_c_time_on']   ?? 0  );
    $referrer   = esc_url_raw(         wp_unslash( $_POST['tz_c_referrer']   ?? '' ) );
    $ua         = sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ?? '' ) );

    if ( empty( $name ) )
        wp_send_json_error( [ 'message' => 'نام الزامی است.' ], 422 );
    if ( mb_strlen( $name ) > 100 )
        wp_send_json_error( [ 'message' => 'نام نباید بیشتر از ۱۰۰ کاراکتر باشد.' ], 422 );
    if ( empty( $phone ) || ! preg_match( '/^[0-9۰-۹\s\-\+]{8,15}$/u', $phone ) )
        wp_send_json_error( [ 'message' => 'شماره تماس معتبر نیست.' ], 422 );

    // FIX 2 (continued): NOW that name + phone have passed validation
    // (and Turnstile already passed above), lock this IP for 60s. A
    // rejected/invalid attempt never consumes the visitor's one
    // submission-per-minute allowance.
    set_transient( $rate_key, 1, 60 );

    $time_label = tz_format_time_on_v6( $time_on );
    $device     = tz_detect_device_v6( $ua );

    tz_save_lead_v6( $name, $phone, $page_url, $page_title, $time_label, $ip, $referrer );

    $html = tz_email_template_v6( $name, $phone, [
        'page_url' => $page_url, 'page_title' => $page_title,
        'time_on' => $time_label, 'time_on_raw' => $time_on,
        'referrer' => $referrer, 'ip' => $ip, 'device' => $device,
    ] );

    $recipients = array_filter( array_map( 'trim', explode( ',', TZ_MAIL_RECIPIENTS ) ), 'is_email' );
    if ( empty( $recipients ) ) {
        error_log( '[TZ FLOAT] no valid recipients' );
        wp_send_json_error( [ 'message' => 'خطای پیکربندی.' ], 500 );
    }

    $sent = wp_mail(
        array_values( $recipients ),
        '📞 درخواست تماس — ' . $name . ' | ' . $phone,
        $html,
        [ 'Content-Type: text/html; charset=UTF-8', 'From: تزنویسه <' . TZ_SMTP_FROM . '>' ]
    );

    if ( ! $sent ) {
        global $phpmailer;
        $err = isset( $phpmailer->ErrorInfo ) ? $phpmailer->ErrorInfo : '';
        error_log( '[TZ FLOAT MAIL FAILED] ' . $name . ' | ' . $err );
        wp_send_json_error( [
            'message' => 'ارسال ایمیل ناموفق. مستقیماً تماس بگیرید.',
            'debug'   => ( defined('WP_DEBUG') && WP_DEBUG ) ? $err : null,
        ], 500 );
    }

    wp_send_json_success( [ 'message' => 'ok' ] );
}

function tz_format_time_on_v6( int $s ): string {
    if ( $s <= 0 ) return 'نامشخص';
    if ( $s < 60 ) return $s . ' ثانیه';
    $m = floor( $s / 60 ); $r = $s % 60;
    return $m . ' دقیقه' . ( $r ? ' و ' . $r . ' ثانیه' : '' );
}
function tz_detect_device_v6( string $ua ): string {
    if ( empty($ua) )                    return 'نامشخص';
    if ( preg_match('/iPad/i',    $ua) ) return '📱 تبلت';
    if ( preg_match('/iPhone/i',  $ua) ) return '📱 آیفون';
    if ( preg_match('/Android/i', $ua) ) return '📱 اندروید';
    if ( preg_match('/Mobile/i',  $ua) ) return '📱 موبایل';
    if ( preg_match('/Windows/i', $ua) ) return '🖥 ویندوز';
    if ( preg_match('/Mac/i',     $ua) ) return '🖥 مک';
    return '🖥 دسکتاپ';
}
function tz_save_lead_v6( $name, $phone, $page_url, $page_title, $time_on, $ip, $referrer ) {
    $id = wp_insert_post([
        'post_type'   => 'tz_lead',
        'post_title'  => sanitize_text_field( $name . ' — ' . current_time('Y/m/d H:i') ),
        'post_status' => 'private',
        'meta_input'  => [
            '_tz_lead_name'=>$name,'_tz_lead_phone'=>$phone,'_tz_lead_type'=>'callback',
            '_tz_lead_page_url'=>$page_url,'_tz_lead_page_title'=>$page_title,
            '_tz_lead_time_on'=>$time_on,'_tz_lead_referrer'=>$referrer,
            '_tz_lead_ip'=>$ip,'_tz_lead_time'=>current_time('mysql'),
        ],
    ], true);
    if ( is_wp_error($id) ) error_log('[TZ LEAD] ' . $id->get_error_message());
}

