<script>
(function () {
    'use strict';
    var TZ_CFG = {
        ajax:    <?php echo wp_json_encode( $ajax ); ?>,
        nonce:   <?php echo wp_json_encode( $nonce ); ?>,
        siteKey: <?php echo wp_json_encode( $site_key ); ?>,
        action:  'tz_contact_submit'
    };
    window.dataLayer = window.dataLayer || [];

    function tzTrack(eventName, params) {
        params = params || {};
        window.dataLayer.push(Object.assign({ event: eventName }, params));
        if (typeof window.gtag === 'function' && typeof window.google_tag_manager === 'undefined') {
            window.gtag('event', eventName, params);
        }
        if (typeof window.clarity === 'function') {
            try { window.clarity('event', eventName); } catch (e) {}
            Object.keys(params).forEach(function (k) {
                try { window.clarity('set', k, String(params[k])); } catch (e) {}
            });
        }
    }
    window.tzTrack = tzTrack;

    var tzStartTime = Date.now();
    function tzSecondsOnPage() { return Math.max(0, Math.round((Date.now() - tzStartTime) / 1000)); }

    var tzTsWidgetId = null;
    window.tzTurnstileReady = function () {
        var c = document.getElementById('tz-fc-ts-container');
        if (!c || typeof window.turnstile === 'undefined') return;
        var l = document.getElementById('tz-fc-ts-loading'); if (l) l.style.display = 'none';
        try {
            tzTsWidgetId = window.turnstile.render(c, { sitekey: TZ_CFG.siteKey, theme: 'light', language: 'fa' });
        } catch (e) { console.warn('[TZ] Turnstile render failed:', e); }
    };

    function tzReady(fn){ document.readyState!=='loading'?fn():document.addEventListener('DOMContentLoaded',fn); }

    tzReady(function () {
        var fab=document.getElementById('tz-fc-fab'),
            panel=document.getElementById('tz-fc-panel'),
            closeBtn=document.getElementById('tz-fc-close-btn'),
            tooltip=document.getElementById('tz-fc-tooltip'),
            notif=document.getElementById('tz-fc-notif'),
            form=document.getElementById('tz-fc-callback-form'),
            msgBox=document.getElementById('tz-fc-form-msg'),
            submit=document.getElementById('tz-fc-cb-submit');

        if (!fab || !panel) return;

        function openPanel(){
            panel.classList.add('open'); panel.setAttribute('aria-hidden','false');
            fab.classList.add('open'); fab.setAttribute('aria-expanded','true'); fab.setAttribute('aria-label','بستن پنل تماس');
            if(notif) notif.style.display='none'; if(tooltip) tooltip.classList.remove('show');
            tzTrack('float_widget_open');
        }
        function closePanel(){
            panel.classList.remove('open'); panel.setAttribute('aria-hidden','true');
            fab.classList.remove('open'); fab.setAttribute('aria-expanded','false'); fab.setAttribute('aria-label','باز کردن پنل تماس');
            tzTrack('float_widget_close');
        }
        fab.addEventListener('click',function(){ panel.classList.contains('open')?closePanel():openPanel(); });
        if(closeBtn) closeBtn.addEventListener('click',closePanel);
        document.addEventListener('keydown',function(e){ if(e.key==='Escape'&&panel.classList.contains('open')) closePanel(); });

        if(tooltip){
            setTimeout(function(){
                if(!panel.classList.contains('open')) tooltip.classList.add('show');
                setTimeout(function(){ tooltip.classList.remove('show'); },6000);
            },4000);
        }

        var tabs=document.querySelectorAll('.tz-fc-tab'), panes=document.querySelectorAll('.tz-fc-pane');
        tabs.forEach(function(tab){
            tab.addEventListener('click',function(){
                var target=this.getAttribute('data-tab');
                tabs.forEach(function(t){ var on=t===tab; t.classList.toggle('active',on); t.setAttribute('aria-selected',on?'true':'false'); });
                panes.forEach(function(p){ p.classList.toggle('active',p.id==='tz-tab-'+target); });
                tzTrack('float_tab_switch',{ tab_name:target });
            });
        });

        document.querySelectorAll('.tz-fc-ch').forEach(function(el){
            el.addEventListener('click',function(){
                var url=(this.getAttribute('href')||'').toLowerCase(), channel='unknown';
                if(/wa\.me|whatsapp/.test(url))      channel='whatsapp';
                else if(/t\.me|telegram/.test(url))  channel='telegram';
                else if(/eitaa/.test(url))           channel='eitaa';
                else if(/rubika/.test(url))          channel='rubika';
                else if(/ble\.ir|bale/.test(url))    channel='bale';
                else if(/^sms:/.test(url))           channel='sms';
                else if(/^tel:/.test(url))           channel='direct_call';
                tzTrack('floating_chat_click',{ contact_platform:channel });
                if(typeof window.clarity==='function'){ try{ window.clarity('event','chat_click_'+channel); }catch(e){} }
            });
        });

        if(form){
            var started=false;
            form.addEventListener('focusin',function(){ if(started) return; started=true; tzTrack('form_start',{ form_name:'floating_callback' }); });
        }

        function showMsg(t,type){ if(!msgBox) return; msgBox.textContent=t; msgBox.classList.remove('ok','err'); msgBox.classList.add(type); }

        if(form){
            form.addEventListener('submit',function(e){
                e.preventDefault();
                var f=function(id){ return document.getElementById(id); };
                if(f('tz_c_page_url'))   f('tz_c_page_url').value=window.location.href;
                if(f('tz_c_page_title')) f('tz_c_page_title').value=document.title;
                if(f('tz_c_time_on'))    f('tz_c_time_on').value=tzSecondsOnPage();
                if(f('tz_c_referrer'))   f('tz_c_referrer').value=document.referrer||'';

                var tsToken='';
                if(typeof window.turnstile!=='undefined'&&tzTsWidgetId!==null){ try{ tsToken=window.turnstile.getResponse(tzTsWidgetId)||''; }catch(er){} }
                if(!tsToken){
                    showMsg('لطفاً تأیید امنیتی را تکمیل کنید.','err');
                    tzTrack('form_submit_error',{ reason:'turnstile_missing' });
                    if(typeof window.clarity==='function'){ try{ window.clarity('event','callback_form_error'); }catch(e){} }
                    return;
                }
                var fd=new FormData(form);
                fd.append('action',TZ_CFG.action); fd.append('_nonce',TZ_CFG.nonce); fd.append('cf-turnstile-response',tsToken);
                if(submit) submit.disabled=true;

                fetch(TZ_CFG.ajax,{ method:'POST', credentials:'same-origin', body:fd })
                .then(function(res){ return res.json().then(function(j){ return { status:res.status, json:j }; }); })
                .then(function(out){
                    var ok=out.json&&out.json.success, data=(out.json&&out.json.data)?out.json.data:{};
                    if(ok){
                        showMsg('درخواست شما ثبت شد. به‌زودی با شما تماس می‌گیریم. ✓','ok');
                        form.reset();
                        if(typeof window.turnstile!=='undefined'&&tzTsWidgetId!==null){ try{ window.turnstile.reset(tzTsWidgetId); }catch(e){} }
                        tzTrack('generate_lead',{ event_category:'Contact Form', event_label:'Floating Panel Request', value:1.0, currency:'IRR' });
                        if(typeof window.clarity==='function'){ try{ window.clarity('event','callback_form_submitted'); }catch(e){} }
                    } else if(out.status===429||(data&&data.rate_limited)){
                        showMsg((data&&data.message)||'لطفاً کمی صبر کنید.','err');
                        tzTrack('form_rate_limited',{ reason:'rate_limit' });
                        if(typeof window.clarity==='function'){ try{ window.clarity('event','callback_rate_limited'); }catch(e){} }
                    } else {
                        var reason=(data&&data.message)?data.message:'unknown';
                        showMsg(reason,'err');
                        if(typeof window.turnstile!=='undefined'&&tzTsWidgetId!==null){ try{ window.turnstile.reset(tzTsWidgetId); }catch(e){} }
                        tzTrack('form_submit_error',{ reason:reason });
                        if(typeof window.clarity==='function'){ try{ window.clarity('event','callback_form_error'); }catch(e){} }
                    }
                })
                .catch(function(){
                    showMsg('خطای شبکه. دوباره تلاش کنید.','err');
                    tzTrack('form_submit_error',{ reason:'network' });
                    if(typeof window.clarity==='function'){ try{ window.clarity('event','callback_form_error'); }catch(e){} }
                })
                .finally(function(){ if(submit) submit.disabled=false; });
            });
        }
    });
})();
</script>
