if ( ! defined( 'TZ_TURNSTILE_SECRET_KEY' ) )
    define( 'TZ_TURNSTILE_SECRET_KEY', '0x4AAAAAADkJzH-L5mTEq0QSyQeB5euOEaY' );  // ← Secret Key

/* ============================================================
