   ============================================================ */
add_action( 'wp_enqueue_scripts', 'tz_turnstile_enqueue' );

function tz_turnstile_enqueue() {
    wp_enqueue_script(
        'cf-turnstile',
        'https://challenges.cloudflare.com/turnstile/v0/api.js',
        [],
        null,
        true // در footer بارگذاری شود
    );
}

/* ============================================================
   ۳. تابع مرکزی تأیید توکن Turnstile (سرور)
   ============================================================ */
function tz_verify_turnstile( string $token, string $ip = '' ): bool {

    if ( empty( $token ) ) return false;

    $response = wp_remote_post(
        'https://challenges.cloudflare.com/turnstile/v0/siteverify',
        [
            'timeout' => 10,
            'body'    => [
                'secret'   => TZ_TURNSTILE_SECRET_KEY,
                'response' => $token,
                'remoteip' => $ip ?: tz_get_client_ip(),
            ],
        ]
    );

    if ( is_wp_error( $response ) ) {
        error_log( '[TZ TURNSTILE] خطای اتصال: ' . $response->get_error_message() );
        return false;
    }

    $body = json_decode( wp_remote_retrieve_body( $response ), true );

    if ( empty( $body['success'] ) ) {
        error_log( '[TZ TURNSTILE] تأیید ناموفق: ' . wp_json_encode( $body['error-codes'] ?? [] ) );
        return false;
    }

    return true;
}

/* ============================================================
   ۴. تابع کمکی: رندر ویجت Turnstile (HTML)
      $form_id → شناسه یکتا برای هر فرم
   ============================================================ */
function tz_turnstile_widget( string $form_id = 'default' ): string {
    return sprintf(
        '<div class="cf-turnstile tz-turnstile-widget"
              data-sitekey="%s"
              data-callback="tzTurnstileCallback_%s"
              data-expired-callback="tzTurnstileExpired_%s"
              data-error-callback="tzTurnstileError_%s"
              data-theme="light"
              data-language="fa"
              data-size="normal"
              id="tz-turnstile-%s"
              aria-label="تأیید امنیتی Cloudflare Turnstile"></div>',
        esc_attr( TZ_TURNSTILE_SITE_KEY ),
        esc_attr( $form_id ),
        esc_attr( $form_id ),
        esc_attr( $form_id ),
        esc_attr( $form_id )
    );
}

/* ============================================================
   ۵. تزریق JS callback برای هر فرم در footer
   ============================================================ */
add_action( 'wp_footer', 'tz_turnstile_callbacks', 5 );

function tz_turnstile_callbacks() {
