/* ============================================================
   ۷. Hook روی هندلر فرم مشاوره اصلی
      تأیید Turnstile قبل از هر پردازشی
   ============================================================ */
add_action( 'wp_ajax_tz_contact_submit',        'tz_turnstile_check_main', 1 );
add_action( 'wp_ajax_nopriv_tz_contact_submit', 'tz_turnstile_check_main', 1 );

function tz_turnstile_check_main() {
    $token = sanitize_text_field( wp_unslash( $_POST['cf-turnstile-response'] ?? '' ) );

    if ( ! tz_verify_turnstile( $token ) ) {
        wp_send_json_error( [
            'message' => 'تأیید امنیتی ناموفق بود. لطفاً دوباره تلاش کنید.',
            'code'    => 'turnstile_failed',
        ], 403 );
    }
    // ✅ اگر تأیید شد → ادامه به هندلر اصلی
}

/* ============================================================
   ۸. Hook روی هندلر دکمه شناور
