/* ============================================================
   ۹. فیلتر: تزریق ویجت به شورت‌کد فرم مشاوره
      این فیلتر خروجی ob_get_clean شورت‌کد را پردازش می‌کند
      و ویجت + input مخفی را قبل از دکمه submit اضافه می‌کند
   ============================================================ */
add_filter( 'tz_thesis_form_before_submit', 'tz_inject_turnstile_main_form' );

function tz_inject_turnstile_main_form( string $html ): string {
    $widget = '
    <!-- Turnstile — فرم اصلی -->
    <input type="hidden" id="tz-turnstile-token-main" name="cf-turnstile-response" value="" />
    ' . tz_turnstile_widget( 'main_form' ) . '
    <div class="tz-turnstile-error" id="tz-turnstile-err-main"
         role="alert" aria-live="assertive">
        ⚠️ لطفاً تأیید امنیتی را تکمیل کنید.
    </div>';

    // درج قبل از دکمه submit فرم اصلی
    return str_replace(
        '<button type="submit" class="tzth-form-submit"',
        $widget . '<button type="submit" class="tzth-form-submit"',
        $html
    );
}
